ROOT=Path(__file__).parent; D=ROOT/'dist';D.mkdir(exist_ok=True)
favicon="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='8' fill='%23f28b66'/%3E%3Cpath d='M11 9v22m18-22v22M11 20h18' stroke='%23141516' stroke-width='5'/%3E%3C/svg%3E"
def page(title,body,active=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#131516"><title>{title} — Harwness</title><meta name="description" content="Harwness is a local Rust agent runtime with typed authority, durable planning, scoped retrieval, and Detect · Orient · Defend."><link rel="icon" type="image/svg+xml" href="{favicon}"><link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/" aria-label="Harwness home"><span class="mark">h</span>harwness<span class="brand-dot">.</span></a><nav aria-label="Main navigation"><a {'aria-current="page"' if active=='overview' else ''} href="/">Overview</a><a {'aria-current="page"' if active=='architecture' else ''} href="/architecture/">Architecture</a><a {'aria-current="page"' if active=='docs' else ''} href="/docs/">Documentation</a></nav><a class="nav-cta" href="/docs/#start">Build from source <span aria-hidden="true">↗</span></a></header><main id="main">{body}</main><footer><div><a class="brand" href="/"><span class="mark">h</span>harwness.</a><p>Intelligence, with boundaries.</p></div><div><a href="/architecture/">Explore the architecture</a><a href="/docs/#status">Development status</a><span class="mono">harw.dev / harwness.dev</span></div><div class="footer-note">Built in Rust. Designed for the operator.<br>v0.3.0 · Early development</div></footer></body></html>'''
home='''<section class="hero wrap"><div class="hero-copy"><div class="eyebrow"><span class="tag">HARW / 0.3.0</span> THE LOCAL AGENT RUNTIME</div><h1>Let agents think.<br><em>Keep authority.</em></h1><p class="hero-lead">A Rust runtime for agents that research, plan, and work.<br class="desktop"> Explicit permissions. Durable state. You in control.</p><div class="actions"><a class="button primary" href="/docs/#start">Start building <span>↗</span></a><a class="button quiet" href="/architecture/">Explore the architecture <span>→</span></a></div><div class="hero-foot mono">LOCAL RUNTIME <span>/</span> PROVIDER-NEUTRAL CORE <span>/</span> TYPED AUTHORITY</div></div><div class="runtime-map" aria-label="Conceptual tool execution flow"><div class="map-caption mono"><span>THE EXECUTION BOUNDARY</span><span>01 / RUNTIME</span></div><div class="map-node model-node"><span class="node-icon">λ</span><div><small>MODEL</small><strong>Propose an intent</strong></div><span class="node-code">untrusted</span></div><div class="connection"><span>tool call</span></div><div class="boundary"><div class="boundary-title mono">HARW AUTHORITY BOUNDARY <span>⌑</span></div><div class="gate-row"><span>01</span><strong>Resolve authority</strong><small>typed context</small></div><div class="gate-row"><span>02</span><strong>Check policy</strong><small>scope + approval</small></div><div class="gate-row"><span>03</span><strong>Admit execution</strong><small>bounded effect</small></div></div><div class="connection"><span>only if permitted</span></div><div class="map-tools"><span>Filesystem</span><span>Process</span><span>Network</span></div><div class="map-bottom mono">PROMPTS ARE INPUT. PERMISSIONS ARE CODE.</div></div></section>
<div class="principle-strip"><span>01 <b>Authority is derived</b></span><span>02 <b>Privileges only narrow</b></span><span>03 <b>Work survives the turn</b></span><span>04 <b>Evidence stays traceable</b></span></div>
<section class="wrap section" id="runtime"><div class="section-heading"><div><div class="eyebrow">A HARNESS WITH A POINT OF VIEW</div><h2>More than an agent loop.</h2></div><p>The model proposes the next step. Harwness owns the contracts, context, and execution that make it real.</p></div><div class="feature-grid"><article class="feature feature-wide"><span class="feature-number mono">01 / GOVERNED WORK</span><h3>Agents with a contract.</h3><p>Compile layered TOML definitions into executable, content-addressed agent snapshots. Give each role a tool surface, a budget, and a return contract.</p><div class="contract-code"><span class="code-dim">[tools]</span><br>admitted <span class="code-dim">=</span> <span class="code-string">["fs.read", "fs.search"]</span><br>forbidden <span class="code-dim">=</span> <span class="code-string">["fs.write", "shell.exec"]</span><br><br><span class="code-dim">[spawn.budget]</span><br>max_tool_calls <span class="code-dim">=</span> <span class="code-num">40</span></div><a class="text-link" href="/docs/#agents">Understand agent definitions ↗</a></article><article class="feature"><span class="feature-number mono">02 / CONTINUITY</span><h3>Work that remembers<br>where it was going.</h3><p>Goals, plan graphs, findings, transcripts, and jobs have a life beyond a single context window. Leases, budgets, and cancellation give background work explicit limits.</p><div class="mini-plan"><div><span class="plan-check">✓</span> Explore the workspace</div><div><span class="plan-check">✓</span> Attach research evidence</div><div><span class="plan-index">03</span> Execute a scoped plan node</div><div class="muted"><span class="plan-index">04</span> Verify against the goal</div></div><span class="example-note">Illustrative plan</span></article><article class="feature"><span class="feature-number mono">03 / CONTEXT & LENS</span><h3>The right evidence.<br>Within the right scope.</h3><p>Typed context distinguishes instructions from evidence. Lens combines chunking, vector and lexical search, ranking, and visibility checks across local indices.</p><div class="lens-tags"><span>Source provenance</span><span>BM25 + vectors</span><span>Budgeted context</span><span>Scoped retrieval</span></div><a class="text-link" href="/docs/#lens">Inside Lens ↗</a></article></div></section>
<section class="dod-section"><div class="wrap dod-layout"><div><div class="eyebrow">DoD / THE HOST SECURITY PLANE</div><h2>Detect.<br>Orient.<br><em>Defend.</em></h2><p>Observe host activity. Turn signals into evidenced findings. Keep privileged responses behind a separate authorization boundary.</p><a class="text-link" href="/docs/#dod">Follow the security pipeline ↗</a></div><div class="dod-steps"><article><span class="step-num">D</span><div><h3>Detect</h3><p>Scoped sensors for host resources, workspace drift, scanner reports, filesystem events, and eBPF signals.</p><span class="mono">SENSORS → TYPED SIGNALS</span></div></article><article><span class="step-num">O</span><div><h3>Orient</h3><p>Rules, baselines, evidence, and triage turn observations into findings. A model verdict is a proposal.</p><span class="mono">RULE-CHECKED → TRIAGED</span></div></article><article><span class="step-num">D</span><div><h3>Defend</h3><p>A separate Warden checks authorization proofs before dispatching privileged host actions.</p><span class="mono">AUTHORIZED → ENFORCED</span></div></article><div class="subtle-note">Optional Linux subsystem · separate Cargo workspace · host setup required</div></div></div></section>
<section class="wrap section"><div class="section-heading"><div><div class="eyebrow">ONE RUNTIME, DISTINCT ENTRY POINTS</div><h2>Choose your surface.<br>Keep the boundary.</h2></div><p>Different entry points receive different capabilities. Connecting a channel does not grant it your local terminal’s authority.</p></div><div class="surface-grid"><article><span class="surface-symbol">&gt;_</span><h3>Terminal & CLI</h3><p>Interactive sessions, one-shot work, workspace analysis, setup, and operator approvals.</p><span class="pill">Local operator</span></article><article><span class="surface-symbol">{ }</span><h3>Rust SDK</h3><p>Compose typed providers, extensions, plans, and sessions through the <code>harw</code> facade.</p><span class="pill">Embeddable</span></article><article><span class="surface-symbol">⌘</span><h3>MCP & Telegram</h3><p>Durable MCP job submission and opt-in paired Telegram ingress, with restricted runtime profiles.</p><span class="pill">Explicit admission</span></article><article><span class="surface-symbol">▤</span><h3>Local control plane</h3><p>Expose governed operations over a Unix socket with peer identity checks. Web UI coverage is evolving.</p><span class="pill">Scoped operations</span></article></div></section>
<section class="wrap architecture-banner"><div><div class="eyebrow">BUILT FROM THE FOUNDATIONS UP</div><h2>Every crate has a role.<br>Every boundary has an owner.</h2><p>Explore the packages, their dependencies, and the consumers that connect the system.</p><a class="button primary" href="/architecture/">Explore 101 packages <span>→</span></a></div><div class="arch-stats"><div><strong>68</strong><span>Product workspace packages</span></div><div><strong>32</strong><span>DoD workspace packages</span></div><div><strong>01</strong><span>Separate mobile policy core</span></div></div></section>
<section class="wrap closing"><div><span class="eyebrow">EARLY BY DESIGN. EXPLICIT ABOUT IT.</span><h2>Build with the boundaries in view.</h2><p>Harwness 0.3.0 is in active development. Start locally, inspect the architecture, and expect APIs to evolve.</p></div><a class="button outline" href="/docs/">Read the documentation ↗</a></section>'''
(D/'index.html').write_text(page('Intelligence, with boundaries',home,'overview'))
architecture='''<section class="wrap page-intro"><div class="eyebrow">ARCHITECTURE / SOURCE SNAPSHOT 0.3.0</div><h1>A system you<br>can <em>trace.</em></h1><p>Follow the foundations into runtime composition, then out to every direct and transitive consumer.</p></section><section class="wrap architecture-summary"><div><strong>68 + 32 + 1</strong><span>Product · DoD · separate mobile core</span></div><div><strong>17 levels</strong><span>Declared normal + build dependencies</span></div><div><strong>2 workspaces</strong><span>Distinct product and host-security builds</span></div></section><section class="wrap section explorer-section"><div class="section-heading"><div><div class="eyebrow">CRATE EXPLORER</div><h2>Start at a leaf. Follow the impact.</h2></div></div><p class="explainer">This graph describes local manifest dependencies, including optional edges. It is not a resolved Cargo feature graph or a promise that every path runs by default. Dev dependencies are listed separately.</p><div class="explorer-controls"><label>Find a package<input id="crate-search" type="search" placeholder="Try authority, lens, or sentinel…" autocomplete="off"></label><label>Build domain<select id="domain-filter"><option value="all">All packages</option><option>Product</option><option>DoD</option><option>Standalone</option></select></label><span id="result-count" class="mono" aria-live="polite"></span></div><div class="explorer"><div class="crate-list" id="crate-list" aria-label="Packages"></div><article class="crate-detail" id="crate-detail" aria-live="polite"></article></div><noscript><p>Enable JavaScript to use the package explorer. The system overview and documentation remain available below.</p></noscript></section><section class="wrap section"><div class="eyebrow">THE COMPOSITION</div><h2>Small contracts. Explicit connections.</h2><div class="layer-table"><div><span class="mono">FOUNDATIONS</span><h3>Types, authority, filesystem contracts</h3><p><code>harw-types</code>, <code>harw-authority</code>, and <code>harw-fsutil</code> carry the identities, permission algebra, and file boundaries used above them.</p></div><div><span class="mono">CAPABILITIES</span><h3>Context, tools, plans, and state</h3><p>Separate contracts define what can be executed, what can be remembered, and how a unit of work is admitted.</p></div><div><span class="mono">ORCHESTRATION</span><h3>Core sessions and runtime assembly</h3><p><code>harw-core</code> owns the turn loop; bridges connect child agents and durable plans. <code>harw-runtime</code> composes services under the selected entry profile.</p></div><div><span class="mono">CONSUMERS</span><h3>CLI, TUI, SDK, and restricted transports</h3><p>The CLI composes the application. TUI, web, jobs, and gateways each use their own profile rather than inheriting a universal tool surface.</p></div></div></section>'''
(D/'architecture').mkdir(exist_ok=True);(D/'architecture/index.html').write_text(page('Architecture',architecture,'architecture'))
docs='''<div class="wrap docs-layout"><aside class="docs-nav"><span class="eyebrow">DOCUMENTATION</span><a href="#intro">Introduction</a><a href="#start">Build & run</a><a href="#agents">Agent contracts</a><a href="#authority">Authority & execution</a><a href="#planning">Planning & continuity</a><a href="#lens">Context & Lens</a><a href="#models">Providers & models</a><a href="#dod">Detect · Orient · Defend</a><a href="#surfaces">Entry point boundaries</a><a href="#status">Development status</a><a href="/architecture/">Crate explorer ↗</a></aside><div class="docs-content"><section id="intro"><div class="eyebrow">HARW / TECHNICAL OVERVIEW</div><h1>Understand<br>the <em>harness.</em></h1><p class="hero-lead">Harwness runs language-model agents as supervised work. Models produce intents; Rust components own authority, execution, and durable state.</p><div class="callout"><strong>Early development · 0.3.0</strong><p>Interfaces and configuration may change. This source snapshot is intended for local development and inspection, not an unattended production-service claim.</p></div></section><section id="start"><span class="eyebrow">01 / GET STARTED</span><h2>Build and run locally.</h2><p>From a checkout of the project, use a Rust toolchain compatible with the workspace and its locked dependencies. The manifests declare Rust 1.85 and edition 2024. Linux is the primary environment for process isolation and DoD.</p><div class="code-block"><div class="code-header"><span>TERMINAL · FROM THE REPOSITORY ROOT</span><button class="copy" data-copy="build-commands">Copy</button></div><pre id="build-commands"><code>cargo build -p harw-cli
cargo run -p harw-cli -- init
cargo run -p harw-cli -- onboard
cargo run -p harw-cli --</code></pre></div><p><code>init</code> scaffolds the local home; <code>onboard</code> configures a provider and model. With no subcommand, <code>harw</code> opens the terminal client. Model inference follows the configured provider; a local runtime does not imply offline inference.</p><div class="code-block"><div class="code-header"><span>INSPECT YOUR SETUP</span><button class="copy" data-copy="inspect-commands">Copy</button></div><pre id="inspect-commands"><code>harw doctor
harw settings
harw --resume
harw analyze --dry-run
harw --help</code></pre></div><p>Keep credentials in supported secret stores or environment references. Project-local configuration contributes a layer only after explicit project trust. Use <code>harw project trust .</code> for a project you have inspected.</p></section><section id="agents"><span class="eyebrow">02 / AGENT CONTRACTS</span><h2>Definitions become executable contracts.</h2><p>The agent DSL parses TOML, resolves configuration layers, validates authority, and lowers the result to <code>ExecutableAgentIr</code>. A versioned BLAKE3 snapshot identifies the compiled definition.</p><p>Definitions include roles, specialization, admitted and forbidden tools, spawn budgets, context programs, lifecycle rules, and return contracts. Derived definitions narrow the authority inherited from their base.</p><div class="code-block"><div class="code-header"><span>EXPLORER DEFINITION · ILLUSTRATIVE EXCERPT</span></div><pre><code>schema = "harwness.agent/v1"
id = "example.agent.explorer@1"
version = "1.0.0"
role = "worker"
specialization = "explorer"
name = "Explorer"
description = "Read-only workspace exploration."

[tools]
admitted = ["fs.read", "fs.list", "fs.search"]
forbidden = ["fs.write", "shell.exec", "web.fetch"]

[spawn.budget]
max_tokens = 60000
max_tool_calls = 40
max_wall_secs = 180</code></pre></div><p>The closed role set distinguishes UserInterface, RootOrchestrator, ChildOrchestrator, Worker, UiaWorker, and AgentSteward. Specialized definitions cover exploration, research, planning, implementation, memory, and security triage.</p><p>Compilation alone grants no host capability. Runtime assembly and the tool execution boundary still determine what an instance can do.</p><div class="source-note">Source: harw-agent-dsl/src/executable.rs · harw-runtime/src/assembly.rs</div></section><section id="authority"><span class="eyebrow">03 / AUTHORITY</span><h2>A prompt cannot grant permission.</h2><p><code>harw-authority</code> separates requested permissions from granted authority. <code>ToolExecutionContext</code> carries the runtime-established sandbox alongside untrusted tool arguments. Approval composition is conservative: deny outranks ask, which outranks allow.</p><div class="doc-cards"><article><h3>Filesystem</h3><p>Directory-relative, no-follow operations and containment checks protect scoped access. Atomic writes and private-file checks support durable stores.</p></article><article><h3>Processes</h3><p>Bubblewrap profiles govern normal Linux shell execution. Host-profile workers use a separate, explicit, session-bound permit mechanism.</p></article><article><h3>Network</h3><p>Egress policy checks destinations and address classes. Browser automation additionally requires its optional feature, explicit grant, and configured backend.</p></article></div><p>Secrets include hybrid post-quantum envelope mechanisms through the pinned <code>crypt_guard</code> dependency. This describes an implementation choice, not a certification or a blanket security guarantee.</p><div class="source-note">Source: harw-authority · harw-tools · harw-sandbox · harw-egress · harw-secrets</div></section><section id="planning"><span class="eyebrow">04 / DURABLE WORK</span><h2>The goal outlives the context window.</h2><p><code>harw-plan</code> owns goals, plan nodes, dependencies, scopes, and evidence. <code>harw-plan-bridge</code> reconciles findings with plans and translates executable nodes into jobs. Read-only research can fan out; mutations stay attached to explicit work scopes.</p><p><code>harw-job-runtime</code> supplies budgets, leases, retry policies, and stored job types. The running executor is composed above that layer, including the CLI job worker and the core durable runner.</p><p>Transcripts and job records live in the session store. Project-memory wiring captures tool outcomes, flushes and consolidates at session close, and can sweep leftover candidates on startup. Curated knowledge—memory, diary, workbench, kanban, and dream-related artifacts—has a separate store with visibility and promotion boundaries. These artifact types do not imply a complete user interface for every surface.</p><div class="source-note">Source: harw-plan · harw-plan-bridge · harw-job-runtime · harw-session-store · harw-knowledge</div></section><section id="lens"><span class="eyebrow">05 / RETRIEVAL</span><h2>Evidence with provenance.</h2><p>Lens separates chunking, persistence, embeddings, indexing, queries, and federation. Markdown, Rust, and plain-text chunkers feed content-addressed storage. Exact vector search and BM25 supply candidates; ranking and packing fit relevant evidence into a budget.</p><p>Queries check visibility and embedding provenance. Federation queries multiple compatible indices and reports skipped sources. The model-facing <code>lens.ask</code> tool is wired into the planning registry profile.</p><div class="callout"><strong>Embedding configuration matters</strong><p>The default deterministic embedder is a placeholder, not a semantic language model. Configure an embedding endpoint for semantic vectors. The model-facing visibility mapping is intentionally restricted; it is not a complete operator-role authorization system.</p></div><div class="source-note">Source: harw-lens-* · harw-tool-lens/src/provenance.rs · harw-tool-lens/src/scope.rs</div></section><section id="models"><span class="eyebrow">PROVIDERS &amp; MODELS</span><h2>One core. Provider-aware execution.</h2><p>The core consumes a model-provider contract. Concrete HTTP adapters implement Responses, Chat Completions, Anthropic, and Codex paths, preserving provider-specific reasoning and tool-call behavior.</p><p>The model catalog separates declared capabilities, runtime profiles, provenance, and observed behavior. Embedded provider data works without a catalog refresh; optional models.dev enrichment supplements it. Internal tasks can have their own configured model selection.</p><p>Retries, rate limiting, context limits, and cache strategy live in explicit components. Catalog entries and seeded behavior scores are not independently verified performance benchmarks or a promise that every provider combination is supported.</p><div class="source-note">Source: harw-provider · harw-provider-http · harw-model-catalog · harw-cli/src/models.rs</div></section><section id="dod"><span class="eyebrow">06 / DETECT · ORIENT · DEFEND</span><h2>Observe broadly.<br>Authorize precisely.</h2><p>DoD is a separate 32-package Cargo workspace with its own build configuration and lockfile. Its sensors, analysis, privileged probes, and enforcement process have distinct responsibilities.</p><div class="doc-cards"><article><h3>Detect</h3><p>CPU, memory, thermal, block I/O, network counters, GPU, cgroups, listeners, workspace changes, and imported scanner reports. Privileged probes add filesystem and eBPF events.</p></article><article><h3>Orient</h3><p>Typed signals feed rules, baselines, and evidenced findings. Finding states separate raw observations, rule-checked results, and triaged judgments.</p></article><article><h3>Defend</h3><p>Escalation separates proposed actions from authorized actions. Warden verifies an action-bound proof before dispatching privileged actions. The production composition implements cgroup freeze, release, and process-tree termination; network isolation currently fails closed through an unavailable-backend implementation.</p></article></div><p>Sensor availability depends on Linux facilities, build features, capabilities, and deployment configuration. Service/CLI migration is incomplete across DoD binaries; this snapshot is not a fully integrated host-defense deployment. Imported scanner reports are read from disk; the report sensor does not launch a vulnerability scanner.</p><p>Telemetry includes a file sink plus opt-in Prometheus and OTLP export paths. Security and Warden observations have additional routing restrictions.</p><div class="source-note">Source: dod/Cargo.toml · harw-dod-signals · harw-dod-rules · harw-dod-escalate · harw-dod-warden</div></section><section id="surfaces"><span class="eyebrow">07 / ENTRY PROFILES</span><h2>Connected does not mean equally privileged.</h2><p>These are the base ceilings in <code>EntryKind::profile</code>. Definition, scope, mode, and approval checks can restrict them further. Separately governed grants must be inspected on their own paths.</p><div class="table-scroll"><table><thead><tr><th>Entry</th><th>Base workspace / process rights</th><th>When approval is unavailable</th></tr></thead><tbody><tr><td>TUI</td><td>Read, write, execute</td><td>Interactive approval</td></tr><tr><td>One-shot</td><td>Read, write, execute</td><td>Reject the turn</td></tr><tr><td>Local web</td><td>Read ceiling</td><td>Fail</td></tr><tr><td>MCP / prompt job</td><td>No base tools</td><td>Block the job</td></tr><tr><td>Plan-node job</td><td>Read, write ceiling</td><td>Fail</td></tr><tr><td>Telegram / Dream gateway</td><td>No base tools</td><td>Fail</td></tr></tbody></table></div><p>Telegram requires opt-in configuration and pairing. Web operations use Unix-socket peer credentials. The MCP listener validates protocol and session ownership before handing submitted work to the durable supervisor.</p><div class="source-note">Source: harw-runtime/src/spec.rs · harw-cli/src/runtime_*.rs</div></section><section id="status"><span class="eyebrow">08 / DEVELOPMENT STATUS</span><h2>Capabilities, with their conditions.</h2><div class="status-list"><div><strong>Core runtime, CLI, and TUI</strong><span>Implemented and connected in source; runtime behavior still depends on setup.</span></div><div><strong>Browser automation</strong><span>Optional feature and explicit browser authority; Firefox / geckodriver setup required.</span></div><div><strong>Lens</strong><span>Implemented retrieval pipeline; semantic embeddings need configuration.</span></div><div><strong>DoD</strong><span>Separate optional Linux subsystem. Network isolation has no production backend; service/CLI integration is still evolving.</span></div><div><strong>Web interface</strong><span>Local operation transport exists. Some UI views explicitly report unavailable backend routes.</span></div><div><strong>Mobile</strong><span>Separate Android-oriented policy core; not an integrated or shipped Android application.</span></div><div><strong>API stability</strong><span>0.x development APIs. No production-readiness, benchmark, or independent-audit claim.</span></div></div><p class="subtle-note">This overview is grounded in the supplied source snapshot. Package relationships are statically inspected; the full Rust workspace and privileged host services have not been built or executed as part of this website work.</p></section></div></div>'''
(D/'docs').mkdir(exist_ok=True);(D/'docs/index.html').write_text(page('Documentation',docs,'docs'))
